</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const long long MOD1 = 998244353;
const long long MOD2 = 1000000007;
const long long BASE = 1000000;

int n, total, sumArr[15], result;
vector<long long> buckets[15];

void generate(int depth, long long num) {
    if (depth == 7) return;
    total++;
    long long val = ((total - num) % MOD1 + MOD1) % MOD1;
    buckets[depth].push_back(val);
    sumArr[depth] = (sumArr[depth] + val) % MOD2;
    for (int d = 0; d <= 9; ++d) {
        generate(depth + 1, num * 10 + d);
    }
}

void process(long long x) {
    if (x > n) return;
    if (x * BASE + BASE - 1 <= n && x * BASE * 10 > n) {
        long long currentTotal = total;
        for (int i = 0, mul = 1; i <= 6; ++i, mul *= 10) {
            int size = (int)buckets[i].size();
            long long diffVal = ((currentTotal - x * mul) % MOD1 + MOD1) % MOD1;
            int pos = (int)(lower_bound(buckets[i].begin(), buckets[i].end(), (long long)(MOD1 - diffVal)) - buckets[i].begin());
            result = (result + diffVal * size + sumArr[i]) % MOD2;
            result = (result - (long long)MOD1 * (size - pos) % MOD2 + MOD2) % MOD2;
            total += size;
        }
        return;
    }
    total++;
    result = (result + ((total - x) % MOD1 + MOD1) % MOD1) % MOD2;
    for (int d = 0; d <= 9; ++d) {
        process(x * 10 + d);
    }
}

int main() {
    cin >> n;
    generate(0, 0);
    for (int i = 0; i <= 7; ++i) {
        sort(buckets[i].begin(), buckets[i].end());
    }
    total = 0;
    for (int i = 1; i <= 9; ++i) {
        process(i);
    }
    cout << result << endl;
    return 0;
}
